-- Repair only exact IDs generated by the archived pep-demo-v2 loader.
-- Same connection: SET demo.allow_uuid_repair='yes'; then execute this file.
-- No row removal, trigger disabling, or history rewriting. Failures roll back DDL too.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='180s';
DO $$ BEGIN
 IF current_setting('demo.allow_uuid_repair',true) IS DISTINCT FROM 'yes' THEN
  RAISE EXCEPTION 'Demo UUID repair refused: explicit demo.allow_uuid_repair=yes required';
 END IF;
END $$;
SELECT pg_advisory_xact_lock(20261029,1601);
CREATE OR REPLACE FUNCTION pg_temp.repair_old(k text) RETURNS uuid
 LANGUAGE sql IMMUTABLE STRICT AS $$ SELECT md5('pep-demo-v2:'||k)::uuid $$;
CREATE OR REPLACE FUNCTION pg_temp.repair_new(k text) RETURNS uuid
 LANGUAGE plpgsql IMMUTABLE STRICT AS $$
DECLARE b bytea:=decode(md5(uuid_send('4a47ba67-d994-42b8-8ca0-ce2136c9a891'::uuid)||convert_to('pep-demo-v2:'||k,'UTF8')),'hex');
BEGIN
 b:=set_byte(b,6,(get_byte(b,6)&15)|48);
 b:=set_byte(b,8,(get_byte(b,8)&63)|128);
 RETURN encode(b,'hex')::uuid;
END $$;
CREATE TEMP TABLE demo_uuid_map(entity text NOT NULL,old_id uuid NOT NULL,new_id uuid NOT NULL,
 PRIMARY KEY(entity,old_id),UNIQUE(entity,new_id)) ON COMMIT DROP;
CREATE OR REPLACE FUNCTION pg_temp.repair_pair(t text,ok text,nk text) RETURNS void
 LANGUAGE plpgsql AS $$
BEGIN
 EXECUTE format('INSERT INTO demo_uuid_map SELECT %L,$1,$2 WHERE EXISTS (SELECT FROM public.%I WHERE id=$1) ON CONFLICT DO NOTHING',t,t)
 USING pg_temp.repair_old(ok),pg_temp.repair_new(nk);
END $$;
CREATE OR REPLACE FUNCTION pg_temp.repair_resolve(t text,v uuid) RETURNS uuid
 LANGUAGE sql STABLE AS $$ SELECT coalesce((SELECT new_id FROM demo_uuid_map WHERE entity=t AND old_id=v),v) $$;
DO $$
DECLARE k text; nk text; career text; area text; v integer; n integer; phase integer; m integer;
 p record; c record; co uuid; cn uuid; so uuid; sn uuid; eo uuid; en uuid; uo uuid; un uuid;
 ao uuid; an uuid; po uuid; pn uuid; go uuid; gn uuid; ddo uuid; ddn uuid;
BEGIN
 FOREACH k IN ARRAY ARRAY['operator','teacher:1','teacher:2','teacher:3','teacher:4','teacher:5','teacher:6','teacher:7','teacher:8'] LOOP
  PERFORM pg_temp.repair_pair('usuarios',k,k);
  IF k<>'operator' THEN PERFORM pg_temp.repair_pair('personal_academico',k,k); END IF;
  PERFORM pg_temp.repair_pair('virtual_classroom_accounts',pg_temp.repair_old(k)||':lms',pg_temp.repair_new(k)||':lms');
 END LOOP;
 PERFORM pg_temp.repair_pair('personal_academico','coordinator','coordinator');
 PERFORM pg_temp.repair_pair('sedes_ies','campus','campus');
 FOREACH area IN ARRAY ARRAY['salud','ingenieria','agro','derecho','economia','educacion','sociales','comunicacion'] LOOP
  PERFORM pg_temp.repair_pair('areas_conocimiento','area:'||area,'area:'||area);
 END LOOP;
 FOREACH career IN ARRAY ARRAY['medicina','enfermeria','odontologia','salud-publica','sistemas','civil','industrial','agronomia','veterinaria','derecho','administracion','contabilidad','educacion','psicologia','comunicacion','economia'] LOOP
  PERFORM pg_temp.repair_pair('tags_academicos','tag:'||career,'tag:'||career);
  FOR v IN 1..2 LOOP
   k:='program:'||career||':'||v;
   PERFORM pg_temp.repair_pair('programas_academicos',k,k);
   FOR m IN 1..4 LOOP PERFORM pg_temp.repair_pair('componentes_curriculares',k||':module:'||m,k||':module:'||m); END LOOP;
  END LOOP;
 END LOOP;
 FOR p IN SELECT id FROM programas_academicos LOOP
  FOR phase IN 1..3 LOOP
   k:='existing-program:'||p.id||':cohort:'||phase;
   nk:='existing-program:'||pg_temp.repair_resolve('programas_academicos',p.id)||':cohort:'||phase;
   co:=pg_temp.repair_old(k); cn:=pg_temp.repair_new(nk);
   PERFORM pg_temp.repair_pair('cohortes_apertura',k,nk);
   PERFORM pg_temp.repair_pair('planes_pago_cohorte',co||':plan',cn||':plan');
   PERFORM pg_temp.repair_pair('cuotas_plan_pago',pg_temp.repair_old(co||':plan')||':quota',pg_temp.repair_new(cn||':plan')||':quota');
   FOR c IN SELECT id FROM componentes_curriculares WHERE programa_id=p.id LOOP
    k:=co||':schedule:'||c.id; nk:=cn||':schedule:'||pg_temp.repair_resolve('componentes_curriculares',c.id);
    PERFORM pg_temp.repair_pair('programacion_componentes_cohorte',k,nk);
    PERFORM pg_temp.repair_pair('virtual_classroom_courses',pg_temp.repair_old(k)||':lms',pg_temp.repair_new(nk)||':lms');
   END LOOP;
   FOR n IN 1..20 LOOP
    k:=co||':student:'||n; nk:=cn||':student:'||n;
    PERFORM pg_temp.repair_pair('personas_aspirantes',k,nk);
    PERFORM pg_temp.repair_pair('usuarios',k||':user',nk||':user');
    PERFORM pg_temp.repair_pair('titulos_academicos_aspirante',k||':degree',nk||':degree');
    PERFORM pg_temp.repair_pair('inscripciones',k||':enrollment',nk||':enrollment');
    PERFORM pg_temp.repair_pair('virtual_classroom_accounts',pg_temp.repair_old(k||':user')||':lms',pg_temp.repair_new(nk||':user')||':lms');
    eo:=pg_temp.repair_old(k||':enrollment'); en:=pg_temp.repair_new(nk||':enrollment');
    FOREACH k IN ARRAY ARRAY['agreement','payment','audit','dossier','recognition'] LOOP
     PERFORM pg_temp.repair_pair(CASE k WHEN 'agreement' THEN 'acuerdos_pago_inscripcion' WHEN 'payment' THEN 'pagos_inscripcion' WHEN 'audit' THEN 'auditoria_economica' WHEN 'dossier' THEN 'expediente_graduacion_certificacion' ELSE 'solicitudes_convalidacion_acreditacion' END,eo||':'||k,en||':'||k);
    END LOOP;
    ao:=pg_temp.repair_old(eo||':agreement'); an:=pg_temp.repair_new(en||':agreement');
    PERFORM pg_temp.repair_pair('obligaciones_pago',ao||':fee',an||':fee');
    PERFORM pg_temp.repair_pair('obligaciones_pago',ao||':academic',an||':academic');
    PERFORM pg_temp.repair_pair('comprobantes_internos',pg_temp.repair_old(eo||':payment')||':receipt',pg_temp.repair_new(en||':payment')||':receipt');
    PERFORM pg_temp.repair_pair('publicaciones_cientificas_estudiante',pg_temp.repair_old(eo||':dossier')||':publication',pg_temp.repair_new(en||':dossier')||':publication');
    FOR c IN SELECT id FROM componentes_curriculares WHERE programa_id=p.id LOOP
     k:=eo||':grade:'||c.id; nk:=en||':grade:'||pg_temp.repair_resolve('componentes_curriculares',c.id);
     PERFORM pg_temp.repair_pair('matricula_componentes_snepa',k,nk);
     PERFORM pg_temp.repair_pair('notas_snepa_logs',pg_temp.repair_old(k)||':log',pg_temp.repair_new(nk)||':log');
    END LOOP;
   END LOOP;
  END LOOP;
 END LOOP;
END $$;
-- A global identity relation is safe only when each old identity has one destination.
CREATE TEMP TABLE demo_uuid_identity ON COMMIT DROP AS SELECT DISTINCT old_id,new_id FROM demo_uuid_map;
CREATE UNIQUE INDEX ON demo_uuid_identity(old_id);
CREATE UNIQUE INDEX ON demo_uuid_identity(new_id);
DO $$
DECLARE r record; found boolean;
BEGIN
 IF NOT EXISTS(SELECT FROM demo_uuid_map) THEN RETURN; END IF;
 IF EXISTS(SELECT FROM demo_uuid_identity WHERE new_id::text !~ '^[0-9a-f]{8}-[0-9a-f]{4}-3[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$') THEN
  RAISE EXCEPTION 'Demo UUID repair refused: invalid destination'; END IF;
 FOR r IN SELECT DISTINCT entity FROM demo_uuid_map LOOP
  EXECUTE format('SELECT EXISTS(SELECT FROM public.%I t JOIN demo_uuid_map m ON t.id=m.new_id WHERE m.entity=$1)',r.entity) INTO found USING r.entity;
  IF found THEN RAISE EXCEPTION 'Demo UUID repair refused: destination collision in %',r.entity; END IF;
 END LOOP;
 -- Refuse artifacts whose snapshots, fingerprints, or issued bytes cannot be rewritten safely.
 IF EXISTS(SELECT FROM virtual_classroom_exports WHERE
  jsonb_typeof(content_snapshot->'courses') IS DISTINCT FROM 'array' OR
  jsonb_typeof(content_snapshot->'people') IS DISTINCT FROM 'array' OR
  jsonb_typeof(content_snapshot->'issues') IS DISTINCT FROM 'array') THEN
  RAISE EXCEPTION 'Demo UUID repair refused: unverifiable export snapshot';
 END IF;
 IF EXISTS(SELECT FROM virtual_classroom_exports t CROSS JOIN LATERAL
  regexp_matches(encode(t.content_bytes,'escape'),'[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}','g') x
  JOIN demo_uuid_identity m ON lower(x[1])=m.old_id::text) THEN
  RAISE EXCEPTION 'Demo UUID repair refused: embedded identity in export bytes';
 END IF;
 FOR r IN SELECT c.relname,a.attname FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace ns ON ns.oid=c.relnamespace
  WHERE ns.nspname='public' AND c.relkind IN ('r','p') AND a.attnum>0 AND NOT a.attisdropped AND a.atttypid='uuid'::regtype
  AND c.relname IN ('certificados_registro','certificados_eventos','virtual_classroom_grade_previews','sesiones','virtual_classroom_exports') LOOP
  EXECUTE format('SELECT EXISTS(SELECT FROM public.%I t JOIN demo_uuid_identity m ON t.%I=m.old_id)',r.relname,r.attname) INTO found;
  IF found THEN RAISE EXCEPTION 'Demo UUID repair refused: protected history in %',r.relname; END IF;
 END LOOP;
 -- Identity references in text/JSON need domain-specific handling; never replace prose or historical payloads blindly.
 FOR r IN SELECT c.relname,a.attname FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace ns ON ns.oid=c.relnamespace
  WHERE ns.nspname='public' AND c.relkind IN ('r','p') AND a.attnum>0 AND NOT a.attisdropped
  AND a.atttypid IN ('text'::regtype,'varchar'::regtype,'json'::regtype,'jsonb'::regtype) LOOP
  EXECUTE format($q$SELECT EXISTS(SELECT FROM public.%I t CROSS JOIN LATERAL regexp_matches(t.%I::text,'[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}','g') x JOIN demo_uuid_identity m ON lower(x[1])=m.old_id::text)$q$,r.relname,r.attname) INTO found;
  IF found THEN RAISE EXCEPTION 'Demo UUID repair refused: embedded identity in %.%',r.relname,r.attname; END IF;
 END LOOP;
END $$;
-- Capture every UUID foreign key, including composites and later referencing tables.
CREATE TEMP TABLE demo_uuid_fks ON COMMIT DROP AS
 SELECT c.oid,c.conrelid,c.conname,pg_get_constraintdef(c.oid) AS definition,c.condeferrable,c.condeferred,c.convalidated,c.confupdtype
 FROM pg_constraint c WHERE c.contype='f' AND EXISTS(SELECT FROM unnest(c.conkey) key JOIN pg_attribute a ON a.attrelid=c.conrelid AND a.attnum=key WHERE a.atttypid='uuid'::regtype);
DO $$
DECLARE r record;
BEGIN
 IF NOT EXISTS(SELECT FROM demo_uuid_map) THEN RETURN; END IF;
 IF EXISTS(SELECT FROM demo_uuid_fks WHERE confupdtype<>'a') THEN RAISE EXCEPTION 'Demo UUID repair refused: unsupported ON UPDATE action'; END IF;
 FOR r IN SELECT * FROM demo_uuid_fks LOOP
  EXECUTE format('ALTER TABLE %s ALTER CONSTRAINT %I DEFERRABLE INITIALLY DEFERRED',r.conrelid::regclass,r.conname);
 END LOOP;
END $$;
SET CONSTRAINTS ALL DEFERRED;
DO $$
DECLARE r record;
BEGIN
 IF NOT EXISTS(SELECT FROM demo_uuid_map) THEN RETURN; END IF;
 -- Resolve each identity through actual FK column pairs; unrelated UUID values stay untouched.
 FOR r IN WITH RECURSIVE bindings(relid,attnum,entity) AS (
  SELECT c.oid,a.attnum,m.entity FROM (SELECT DISTINCT entity FROM demo_uuid_map) m
   JOIN pg_class c ON c.relname=m.entity JOIN pg_namespace ns ON ns.oid=c.relnamespace AND ns.nspname='public'
   JOIN pg_attribute a ON a.attrelid=c.oid AND a.attname='id'
  UNION
  SELECT fk.conrelid,k.src,b.entity FROM bindings b JOIN pg_constraint fk ON fk.confrelid=b.relid AND fk.contype='f'
   CROSS JOIN LATERAL unnest(fk.conkey,fk.confkey) AS k(src,dst) WHERE k.dst=b.attnum
 ) SELECT b.relid::regclass AS target,a.attname,b.entity FROM bindings b
   JOIN pg_attribute a ON a.attrelid=b.relid AND a.attnum=b.attnum
 LOOP
  EXECUTE format('UPDATE %s t SET %I=m.new_id FROM demo_uuid_map m WHERE m.entity=$1 AND t.%I=m.old_id',r.target,r.attname,r.attname) USING r.entity;
 END LOOP;
 UPDATE virtual_classroom_accounts t SET person_id=m.new_id FROM demo_uuid_map m WHERE t.person_id=m.old_id AND m.entity=CASE t.person_type WHEN 'user' THEN 'usuarios' WHEN 'applicant' THEN 'personas_aspirantes' WHEN 'teacher' THEN 'personal_academico' END;
END $$;
-- Force complete FK validation before restoring exactly the prior deferral flags.
SET CONSTRAINTS ALL IMMEDIATE;
DO $$
DECLARE r record;
BEGIN
 IF NOT EXISTS(SELECT FROM demo_uuid_map) THEN RETURN; END IF;
 FOR r IN SELECT * FROM demo_uuid_fks LOOP
  EXECUTE format('ALTER TABLE %s ALTER CONSTRAINT %I %s',r.conrelid::regclass,r.conname,
   CASE WHEN r.condeferrable THEN 'DEFERRABLE INITIALLY '||CASE WHEN r.condeferred THEN 'DEFERRED' ELSE 'IMMEDIATE' END ELSE 'NOT DEFERRABLE INITIALLY IMMEDIATE' END);
  IF (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE oid=r.oid) IS DISTINCT FROM r.definition THEN
   RAISE EXCEPTION 'Demo UUID repair refused: FK definition changed'; END IF;
 END LOOP;
END $$;
SELECT entity,count(*) AS repaired_identities FROM demo_uuid_map GROUP BY entity ORDER BY entity;
COMMIT;
